fn is_prime(n: i8) -> bool {
    // Numbers less than 2 are not prime
    if n < 2 {
        return false;
    }
    
    // Handle negative numbers (though i8 negative numbers are already < 2)
    if n < 0 {
        return false;
    }
    
    // Check divisors from 2 up to sqrt(n) (optimization)
    // Since n is at most 127 (i8::MAX), we can check up to n-1
    // but checking up to sqrt(n) is sufficient and more efficient
    let limit = (n as f32).sqrt() as i8 + 1;
    
    for divisor in 2..=limit {
        if n % divisor == 0 {
            return false;
        }
    }
    
    // Special case: 2 is prime
    if n == 2 {
        return true;
    }
    
    // If we get here and n > 1, it's prime
    true
}